export function playLabEnding(onDone) {
  // 快进模式跳过通关演出（Agent/批量跑用）：直接进结算，与「跳过」按钮同出口
  if (isTurbo()) { onDone?.(); return; }
  const root = document.createElement('div');
  root.id = 'labEnding';
  root.innerHTML = `
    ${PAGES.map((p, i) => `
      <div class="lab-end-page lab-tone-${p.tone}${i === 0 ? ' on' : ''}" data-page="${i}">
        <div class="lab-end-art" style="background-image:url('${assetUrl(p.img)}')"></div>
        <div class="lab-end-shade"></div>
        <div class="lab-end-text"><span class="lab-end-typed"></span><i class="lab-end-cue">▼</i></div>
      </div>`).join('')}
    <button class="lab-end-skip" type="button">跳过 »</button>`;
  document.body.appendChild(root);

}

function showLabSettlement(s, st) {
  game.state = 'modal';
  SDT.Agent?.recorder?.recordRun('clear', { why: `研究所结算 ${s.total} 分`,   // 跑局统计（数据分析系统）
    carriedCards: (game.ownedCards || []).map(o => ({ card: o.card, count: 1 })) });
  UI.showOverlay('[[icon:exit]] 经典生命研究所 · 行动结算', `
    <p class="ov-stats">战斗表现：击杀 <b>${s.kills}</b> × ${LAB_SCORE.killMinor} = ${s.killPts} 分 · 所主击破 +${s.bossPts} 分 · 队伍状态 +${s.hpPts} 分</p>
    <p class="ov-stats">带回物资：卡牌 ${s.cards} 张 +${s.cardPts} 分 · 符文 ${s.runes} 块 +${s.runePts} 分</p>
    <p class="ov-stats">剩余金币 +${s.coinPts} 分</p>
    <p class="ov-note">本次行动 <b>${s.total}</b> 分 · 累计 ${st.labTotalScore} 分（单局最佳 ${st.labBestScore}）</p>
    <div class="ov-btns"><button class="ov-btn ok" data-act="labScoreBack">接收情报，返回基地</button></div>`, true);
  UI.act('labScoreBack', () => exitToTitle());
}

